import java.io.File;
import java.net.URL;
import java.net.URLClassLoader;
import java.util.ArrayList;
import java.util.List;

public class Launcher {
    public static void main(String[] args) throws Exception {
        // Determine the lib directory relative to the jar location
        String jarDir = new File(Launcher.class.getProtectionDomain()
                .getCodeSource().getLocation().toURI()).getParent();
        File libDir = new File(jarDir, "lib");

        List<URL> urls = new ArrayList<>();
        // Add the jar itself (for classes and resources)
        urls.add(Launcher.class.getProtectionDomain().getCodeSource().getLocation());

        // Add all jars from lib
        if (libDir.exists() && libDir.isDirectory()) {
            File[] jars = libDir.listFiles((d, n) -> n.endsWith(".jar"));
            if (jars != null) {
                for (File jar : jars) {
                    urls.add(jar.toURI().toURL());
                }
            }
        }

        URLClassLoader cl = new URLClassLoader(urls.toArray(new URL[0]),
                Thread.currentThread().getContextClassLoader());
        Thread.currentThread().setContextClassLoader(cl);

        Class<?> mainClass = cl.loadClass("com.workspace.platform.WorkSpaceApplication");
        java.lang.reflect.Method mainMethod = mainClass.getMethod("main", String[].class);
        mainMethod.invoke(null, (Object) args);
    }
}
